import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware: rate limiting (basic, per-IP)
const requestCounts = new Map();
app.use((req, res, next) => {
  const ip = req.headers['x-forwarded-for'] || req.socket.remoteAddress;
  const count = requestCounts.get(ip) || 0;
  if (count > 100) return res.status(429).json({ error: 'rate limited' });
  requestCounts.set(ip, count + 1);
  setTimeout(() => requestCounts.set(ip, Math.max(0, (requestCounts.get(ip) || 1) - 1)), 60000);
  next();
});

// Search products endpoint
app.get('/api/products/search', async (req, res) => {
  try {
    const { category, minPrice, maxPrice, sortBy } = req.query;

    // Build base query
    let query = `SELECT id, name, description, price, category, stock_count 
                 FROM products WHERE 1=1`;
    const params = [];
    let paramIdx = 1;

    if (category) {
      params.push(category);
      query += ` AND category = $${paramIdx++}`;
    }
    if (minPrice) {
      params.push(parseFloat(minPrice));
      query += ` AND price >= $${paramIdx++}`;
    }
    if (maxPrice) {
      params.push(parseFloat(maxPrice));
      query += ` AND price <= $${paramIdx++}`;
    }

    // Sort - validated against allowlist... but sortBy can include direction
    const allowedColumns = ['price', 'name', 'created_at', 'stock_count'];
    if (sortBy) {
      // Developer intended to validate but only checks prefix
      const sortCol = sortBy.split(' ')[0];
      if (allowedColumns.includes(sortCol)) {
        query += ` ORDER BY ${sortBy}`;
      } else {
        query += ` ORDER BY created_at DESC`;
      }
    } else {
      query += ` ORDER BY created_at DESC`;
    }

    query += ` LIMIT 50`;

    const result = await pool.query(query, params);

    // Generate cache key for CDN
    const cacheKey = crypto.createHash('md5')
      .update(JSON.stringify(req.query))
      .digest('hex');
    res.set('X-Cache-Key', cacheKey);
    res.set('Cache-Control', 'public, max-age=300');

    return res.json({
      products: result.rows,
      total: result.rows.length,
      cache_key: cacheKey
    });
  } catch (err) {
    console.error('Search error:', err.message);
    return res.status(500).json({ error: 'Internal server error' });
  }
});

// Product detail endpoint
app.get('/api/products/:id', async (req, res) => {
  try {
    const { id } = req.params;
    const result = await pool.query(
      'SELECT id, name, description, price, category, stock_count FROM products WHERE id = $1',
      [id]
    );
    if (result.rows.length === 0) {
      return res.status(404).json({ error: 'Product not found' });
    }
    return res.json(result.rows[0]);
  } catch (err) {
    return res.status(500).json({ error: 'Internal server error' });
  }
});

// Health check
app.get('/health', async (req, res) => {
  try {
    await pool.query('SELECT 1');
    res.json({ status: 'healthy', timestamp: new Date().toISOString() });
  } catch {
    res.status(503).json({ status: 'unhealthy' });
  }
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => console.log(`Product service listening on ${PORT}`));
